36	// Flip is a pure pixel remap, so it is memory/latency-bound: one element per thread leaves too few
37	// memory requests in flight (ncu on the single-channel uchar kernel: DRAM 45%, "latency issues").
38	// Each thread instead processes NIX columns strided by the total x-thread count, so NIX independent
39	// loads/stores are issued together (memory-level parallelism) while consecutive threads still touch
40	// consecutive columns (coalesced). NIX>1 needs the grid sized to divUp(width, NIX) x-threads. The
41	// remap is unchanged, so every output is bit-exact with the one-element-per-thread version.
42	constexpr int kFlipNIX       = 4;
43	constexpr int kFlipScalarNIX = 1;
44	
45	inline bool CurrentDeviceIsSM86()
46	{
47	    int dev = 0;
48	    if (cudaGetDevice(&dev) != cudaSuccess)
49	        return false;
50	
51	    cudaDeviceProp prop{};
52	    if (cudaGetDeviceProperties(&prop, dev) != cudaSuccess)
53	        return false;
54	
55	    return prop.major == 8 && prop.minor == 6;
56	}
57	
58	template<int NIX, typename SrcWrapper, typename DstWrapper>
59	__global__ void flipHorizontal(SrcWrapper src, DstWrapper dst, Size2D dstSize)
60	{
61	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
62	    const int32_t batch_idx = get_batch_idx();
63	    if (dst_y >= dstSize.h)
64	        return;
65	
66	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
67	    const int32_t stride = gridDim.x * blockDim.x;
68	    const int32_t width  = dstSize.w;
69	
70	#pragma unroll
71	    for (int i = 0; i < NIX; ++i)
72	    {
73	        const int32_t dst_x = x0 + i * stride;
74	        if (dst_x < width)
75	        {
76	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, dst_y, (width - 1 - dst_x));
77	        }
78	    }
79	}
80	
81	template<int NIX, typename SrcWrapper, typename DstWrapper>
82	__global__ void flipVertical(SrcWrapper src, DstWrapper dst, Size2D dstSize)
83	{
84	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
85	    const int32_t batch_idx = get_batch_idx();
86	    if (dst_y >= dstSize.h)
87	        return;
88	
89	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
90	    const int32_t stride = gridDim.x * blockDim.x;
91	    const int32_t width  = dstSize.w;
92	    const int32_t src_y  = dstSize.h - 1 - dst_y;
93	
94	#pragma unroll
95	    for (int i = 0; i < NIX; ++i)
96	    {
97	        const int32_t dst_x = x0 + i * stride;
98	        if (dst_x < width)
99	        {
100	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, src_y, dst_x);
101	        }
102	    }
103	}
