129	template<int NIX, typename SrcWrap, typename DstWrap>
130	void runFlipKernel(SrcWrap src, DstWrap dst, Size2D dstSize, int numSamples, int32_t flipCode, cudaStream_t stream)
131	{
132	    dim3 blockSize(32, 8, 1);
133	    dim3 gridSize(divUp(divUp(dstSize.w, NIX), static_cast<int>(blockSize.x)), divUp(dstSize.h, blockSize.y),
134	                  numSamples);
135	
136	    if (flipCode > 0)
137	    {
138	        flipHorizontal<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
139	        checkKernelErrors();
140	    }
141	    else if (flipCode == 0)
142	    {
143	        flipVertical<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
144	        checkKernelErrors();
145	    }
146	    else
147	    {
148	        flipHorizontalVertical<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
149	        checkKernelErrors();
150	    }
151	}
