153	template<typename T, int NIX>
154	ErrorCode flipImpl(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output, const int32_t flipCode,
155	                   cudaStream_t stream)
156	{
157	    auto outAccess = TensorDataAccessStridedImagePlanar::Create(output);
158	    NVCV_ASSERT(outAccess);
159	
160	    auto inAccess = TensorDataAccessStridedImagePlanar::Create(input);
161	    NVCV_ASSERT(inAccess);
162	
163	    Size2D dstSize{outAccess->numCols(), outAccess->numRows()};
164	
165	    int64_t inMaxStride  = inAccess->sampleStride() * inAccess->numSamples();
166	    int64_t outMaxStride = outAccess->sampleStride() * outAccess->numSamples();
167	    if (std::max(inMaxStride, outMaxStride) <= cuda::TypeTraits<int32_t>::max)
168	    {
169	        auto src = cuda::CreateTensorWrapNHW<const T, int32_t>(input);
170	        auto dst = cuda::CreateTensorWrapNHW<T, int32_t>(output);
171	
172	        runFlipKernel<NIX>(src, dst, dstSize, outAccess->numSamples(), flipCode, stream);
173	    }
174	    else
175	    {
176	        LOG_ERROR("Input or output size exceeds " << cuda::TypeTraits<int32_t>::max << ". Tensor is too large.");
177	        return ErrorCode::INVALID_PARAMETER;
178	    }
179	
180	#ifdef CUDA_DEBUG_LOG
181	    checkCudaErrors(cudaStreamSynchronize(stream));
182	    checkCudaErrors(cudaGetLastError());
183	#endif // CUDA_DEBUG_LOG
184	
185	    return ErrorCode::SUCCESS;
186	}
